(()=>{"use strict";document.addEventListener("DOMContentLoaded",(()=>{const e=document.getElementById("loading-screen"),n=document.getElementById("content");fetch("/api/data").then((e=>e.json())).then((t=>{e.classList.add("hidden"),n.classList.remove("hidden"),n.innerHTML=`<h1>${t.message}</h1>`})).catch((()=>{e.classList.add("hidden"),n.classList.remove("hidden"),n.innerHTML="<h1>Нет соединения с сервером</h1>"}))})),"serviceWorker"in navigator&&window.addEventListener("load",(()=>{navigator.serviceWorker.register("/service-worker.js").then((e=>{console.log("Service Worker зарегистрирован:",e)})).catch((e=>{console.log("Ошибка регистрации Service Worker:",e)}))}))})();